CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown on links and in the member list.
	"display_name" VARCHAR(120) NOT NULL,
	-- Argon2id hash. Null for SSO-only accounts.
	"password_hash" VARCHAR(255),
	-- Hash of the personal API token. Only the hash is stored, so a database leak cannot be replayed against the API.
	"api_token_hash" VARCHAR(255),
	-- Stops link creation immediately. Existing links keep resolving until a moderator decides otherwise.
	"is_suspended" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An account. Links belong to workspaces rather than directly to people, so an individual leaving does not orphan a URL that is printed on a poster somewhere.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown on links and in the member list.';
COMMENT ON COLUMN "users"."password_hash" IS 'Argon2id hash. Null for SSO-only accounts.';
COMMENT ON COLUMN "users"."api_token_hash" IS 'Hash of the personal API token. Only the hash is stored, so a database leak cannot be replayed against the API.';
COMMENT ON COLUMN "users"."is_suspended" IS 'Stops link creation immediately. Existing links keep resolving until a moderator decides otherwise.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "workspaces" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name for the team or project.
	"name" VARCHAR(120) NOT NULL,
	-- URL segment for the dashboard, distinct from any short domain.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Billing owner. Null while an ownership transfer is pending, which is why it is not NOT NULL.
	"owner_id" BIGINT,
	-- free | pro | business. Decides link quotas, custom domains and analytics retention.
	"plan_tier" VARCHAR(24) NOT NULL DEFAULT 'free',
	-- Links creatable per calendar month. Enforced at creation, because rate limiting a redirect is far too late.
	"monthly_link_quota" INTEGER NOT NULL DEFAULT 1000,
	-- Row creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workspaces" IS 'The ownership boundary for links, domains and analytics. Every quota and every permission check resolves here, which keeps the redirect path free of user-level logic.';
COMMENT ON COLUMN "workspaces"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workspaces"."name" IS 'Display name for the team or project.';
COMMENT ON COLUMN "workspaces"."slug" IS 'URL segment for the dashboard, distinct from any short domain.';
COMMENT ON COLUMN "workspaces"."owner_id" IS 'Billing owner. Null while an ownership transfer is pending, which is why it is not NOT NULL.';
COMMENT ON COLUMN "workspaces"."plan_tier" IS 'free | pro | business. Decides link quotas, custom domains and analytics retention.';
COMMENT ON COLUMN "workspaces"."monthly_link_quota" IS 'Links creatable per calendar month. Enforced at creation, because rate limiting a redirect is far too late.';
COMMENT ON COLUMN "workspaces"."created_at" IS 'Row creation time.';

CREATE TABLE IF NOT EXISTS "workspace_members" (
	-- Workspace granted. Part of the composite key.
	"workspace_id" BIGINT,
	-- Member. Part of the composite key, which also stops a duplicate membership.
	"user_id" BIGINT,
	-- viewer | member | admin | owner. Only admin and above can delete a link, because a deleted short code is a dead link in the physical world.
	"role" VARCHAR(16) NOT NULL DEFAULT 'member',
	-- Who added them. Null once that account is deleted.
	"invited_by_id" BIGINT,
	-- Membership start.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("workspace_id", "user_id")
);

COMMENT ON TABLE "workspace_members" IS 'Join table with a composite primary key and no surrogate id. Nothing references a membership, so a second key would be an index to maintain for nothing.';
COMMENT ON COLUMN "workspace_members"."workspace_id" IS 'Workspace granted. Part of the composite key.';
COMMENT ON COLUMN "workspace_members"."user_id" IS 'Member. Part of the composite key, which also stops a duplicate membership.';
COMMENT ON COLUMN "workspace_members"."role" IS 'viewer | member | admin | owner. Only admin and above can delete a link, because a deleted short code is a dead link in the physical world.';
COMMENT ON COLUMN "workspace_members"."invited_by_id" IS 'Who added them. Null once that account is deleted.';
COMMENT ON COLUMN "workspace_members"."joined_at" IS 'Membership start.';

CREATE TABLE IF NOT EXISTS "domains" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning workspace.
	"workspace_id" BIGINT NOT NULL,
	-- The short domain itself, e.g. acme.link. 253 is the DNS maximum. Unique globally - a hostname can only route to one workspace.
	"hostname" VARCHAR(253) NOT NULL UNIQUE,
	-- Used when a link is created without naming a domain.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Random value the owner publishes in a TXT record to prove control before the domain will serve redirects.
	"verification_token" VARCHAR(64) NOT NULL,
	-- Verification time. Null means the domain is configured but will not resolve links yet.
	"verified_at" TIMESTAMPTZ,
	-- pending | issued | failed. Certificate issuance is asynchronous and fails often enough to need its own state.
	"ssl_status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Row creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "domains" IS 'Custom short domains. The uniqueness of a short code is per domain, not global, which is what lets two customers both own /sale without collision.';
COMMENT ON COLUMN "domains"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "domains"."workspace_id" IS 'Owning workspace.';
COMMENT ON COLUMN "domains"."hostname" IS 'The short domain itself, e.g. acme.link. 253 is the DNS maximum. Unique globally - a hostname can only route to one workspace.';
COMMENT ON COLUMN "domains"."is_default" IS 'Used when a link is created without naming a domain.';
COMMENT ON COLUMN "domains"."verification_token" IS 'Random value the owner publishes in a TXT record to prove control before the domain will serve redirects.';
COMMENT ON COLUMN "domains"."verified_at" IS 'Verification time. Null means the domain is configured but will not resolve links yet.';
COMMENT ON COLUMN "domains"."ssl_status" IS 'pending | issued | failed. Certificate issuance is asynchronous and fails often enough to need its own state.';
COMMENT ON COLUMN "domains"."created_at" IS 'Row creation time.';

CREATE INDEX "idx_domains_workspace_default"
ON "domains" ("workspace_id", "is_default");

CREATE TABLE IF NOT EXISTS "code_blocks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application instance that claimed this range, so an orphaned block can be attributed and reclaimed.
	"instance_id" VARCHAR(64) NOT NULL,
	-- First counter value in the block, inclusive.
	"range_start" BIGINT NOT NULL,
	-- Last counter value, inclusive. A block of 10,000 means one database round trip per 10,000 links created.
	"range_end" BIGINT NOT NULL,
	-- Next unused value in the block. Held in memory during normal operation and flushed here so a restart does not reissue codes.
	"next_value" BIGINT NOT NULL,
	-- When the block ran out. Null while it is still in use.
	"exhausted_at" TIMESTAMPTZ,
	-- When the instance took the block.
	"claimed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "code_blocks" IS 'Ranges of the global counter handed out to application instances. It is what makes base62-from-a-counter work without every link creation contending on one sequence, at the cost of leaving gaps when an instance dies mid-block.';
COMMENT ON COLUMN "code_blocks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "code_blocks"."instance_id" IS 'Application instance that claimed this range, so an orphaned block can be attributed and reclaimed.';
COMMENT ON COLUMN "code_blocks"."range_start" IS 'First counter value in the block, inclusive.';
COMMENT ON COLUMN "code_blocks"."range_end" IS 'Last counter value, inclusive. A block of 10,000 means one database round trip per 10,000 links created.';
COMMENT ON COLUMN "code_blocks"."next_value" IS 'Next unused value in the block. Held in memory during normal operation and flushed here so a restart does not reissue codes.';
COMMENT ON COLUMN "code_blocks"."exhausted_at" IS 'When the block ran out. Null while it is still in use.';
COMMENT ON COLUMN "code_blocks"."claimed_at" IS 'When the instance took the block.';

CREATE INDEX "idx_code_blocks_instance_active"
ON "code_blocks" ("instance_id", "exhausted_at");

CREATE TABLE IF NOT EXISTS "links" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning workspace.
	"workspace_id" BIGINT NOT NULL,
	-- Short domain this code lives under. Null means the default system domain.
	"domain_id" BIGINT,
	-- The path segment after the domain. Base62-encoded counter value for generated codes, or the user string for a custom one. Case-sensitive, because base62 needs both cases to stay short.
	"short_code" VARCHAR(32) NOT NULL,
	-- Counter value the code was encoded from. Null for a custom alias, which is exactly how the system tells the two apart without parsing the string.
	"code_value" BIGINT,
	-- Where the redirect goes. TEXT because URLs with tracking parameters routinely pass 2,000 characters and a varchar limit here is a bug waiting for a marketing campaign.
	"destination_url" TEXT NOT NULL,
	-- Fetched page title, shown in the dashboard so a list of codes is readable.
	"title" VARCHAR(200),
	-- Author. Null once that account is deleted - the link must outlive the person who made it.
	"created_by_id" BIGINT,
	-- True when the user chose the code. Custom aliases are never recycled, while a generated code could in principle be.
	"is_custom_alias" BOOLEAN NOT NULL DEFAULT false,
	-- 301 | 302 | 307 | 308. Defaults to 302 on purpose: a 301 is cached by browsers effectively forever, and a link whose destination can be edited must not be permanently cached.
	"redirect_status" SMALLINT NOT NULL DEFAULT 302,
	-- Optional gate before the redirect. Null for an open link.
	"password_hash" VARCHAR(255),
	-- Hard expiry. Null means the link never expires by time.
	"expires_at" TIMESTAMPTZ,
	-- Click cap. Null means unlimited; when set, the link stops resolving once click_count reaches it.
	"max_clicks" INTEGER,
	-- Denormalised total. Maintained on the redirect path because enforcing max_clicks by counting the event log on every request would put an aggregate query in front of every visitor.
	"click_count" BIGINT NOT NULL DEFAULT 0,
	-- Most recent hit, for the "unused links" report.
	"last_clicked_at" TIMESTAMPTZ,
	-- Manual or automated kill switch. Set by moderation rather than deleting the row, so the code cannot be reissued to a different destination.
	"is_disabled" BOOLEAN NOT NULL DEFAULT false,
	-- Soft delete. A deleted short code keeps its row forever; reusing it would silently redirect an old printed QR code somewhere new.
	"deleted_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "links" IS 'The redirect itself. Everything the hot path needs - destination, status code, expiry, cap, disabled flag - is on this one row, so resolving a link is a single index lookup and never a join.';
COMMENT ON COLUMN "links"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "links"."workspace_id" IS 'Owning workspace.';
COMMENT ON COLUMN "links"."domain_id" IS 'Short domain this code lives under. Null means the default system domain.';
COMMENT ON COLUMN "links"."short_code" IS 'The path segment after the domain. Base62-encoded counter value for generated codes, or the user string for a custom one. Case-sensitive, because base62 needs both cases to stay short.';
COMMENT ON COLUMN "links"."code_value" IS 'Counter value the code was encoded from. Null for a custom alias, which is exactly how the system tells the two apart without parsing the string.';
COMMENT ON COLUMN "links"."destination_url" IS 'Where the redirect goes. TEXT because URLs with tracking parameters routinely pass 2,000 characters and a varchar limit here is a bug waiting for a marketing campaign.';
COMMENT ON COLUMN "links"."title" IS 'Fetched page title, shown in the dashboard so a list of codes is readable.';
COMMENT ON COLUMN "links"."created_by_id" IS 'Author. Null once that account is deleted - the link must outlive the person who made it.';
COMMENT ON COLUMN "links"."is_custom_alias" IS 'True when the user chose the code. Custom aliases are never recycled, while a generated code could in principle be.';
COMMENT ON COLUMN "links"."redirect_status" IS '301 | 302 | 307 | 308. Defaults to 302 on purpose: a 301 is cached by browsers effectively forever, and a link whose destination can be edited must not be permanently cached.';
COMMENT ON COLUMN "links"."password_hash" IS 'Optional gate before the redirect. Null for an open link.';
COMMENT ON COLUMN "links"."expires_at" IS 'Hard expiry. Null means the link never expires by time.';
COMMENT ON COLUMN "links"."max_clicks" IS 'Click cap. Null means unlimited; when set, the link stops resolving once click_count reaches it.';
COMMENT ON COLUMN "links"."click_count" IS 'Denormalised total. Maintained on the redirect path because enforcing max_clicks by counting the event log on every request would put an aggregate query in front of every visitor.';
COMMENT ON COLUMN "links"."last_clicked_at" IS 'Most recent hit, for the "unused links" report.';
COMMENT ON COLUMN "links"."is_disabled" IS 'Manual or automated kill switch. Set by moderation rather than deleting the row, so the code cannot be reissued to a different destination.';
COMMENT ON COLUMN "links"."deleted_at" IS 'Soft delete. A deleted short code keeps its row forever; reusing it would silently redirect an old printed QR code somewhere new.';
COMMENT ON COLUMN "links"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_links_domain_code"
ON "links" ("domain_id", "short_code");
CREATE INDEX "idx_links_workspace_created"
ON "links" ("workspace_id", "created_at");
CREATE INDEX "idx_links_expires"
ON "links" ("expires_at");

CREATE TABLE IF NOT EXISTS "link_tags" (
	-- Tagged link. Part of the composite key.
	"link_id" BIGINT,
	-- Tag text. Part of the composite key, so the tag string is the identity - a link shortener has no use for a tag entity with its own lifecycle.
	"tag" VARCHAR(60),
	-- When the tag was applied.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("link_id", "tag")
);

COMMENT ON TABLE "link_tags" IS 'Free-text labels for filtering the dashboard. Deliberately denormalised into a string key: renaming a tag across a workspace is a single UPDATE, and nothing else in the system references tags.';
COMMENT ON COLUMN "link_tags"."link_id" IS 'Tagged link. Part of the composite key.';
COMMENT ON COLUMN "link_tags"."tag" IS 'Tag text. Part of the composite key, so the tag string is the identity - a link shortener has no use for a tag entity with its own lifecycle.';
COMMENT ON COLUMN "link_tags"."created_at" IS 'When the tag was applied.';

CREATE INDEX "idx_link_tags_tag"
ON "link_tags" ("tag");

CREATE TABLE IF NOT EXISTS "click_events" (
	-- Monotonic event id. In production this table is partitioned by day and old partitions are dropped rather than deleted row by row.
	"id" BIGSERIAL,
	-- Link that was hit.
	"link_id" BIGINT NOT NULL,
	-- Hit time. Also the partition key.
	"occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Salted hash of the client address. The raw IP is never stored - the only question analytics asks is "same visitor?", and a hash answers it without keeping personal data.
	"ip_hash" VARCHAR(64),
	-- ISO 3166-1 alpha-2 from geo-IP lookup. Null when the lookup fails.
	"country_code" CHAR(2),
	-- Resolved city, when the geo database has one.
	"city" VARCHAR(120),
	-- Referring URL as sent by the browser, truncated by the application. Null for a direct hit.
	"referer" TEXT,
	-- Raw UA string, kept for reprocessing when the parser improves.
	"user_agent" TEXT,
	-- desktop | mobile | tablet | bot. Parsed at write time, because parsing 50 million UA strings at read time is not a report, it is an outage.
	"device_type" VARCHAR(20),
	-- Parsed browser family.
	"browser" VARCHAR(40),
	-- Parsed operating system family.
	"os" VARCHAR(40),
	-- Excluded from the headline click number. Crawlers can be most of the traffic on a public link, and counting them makes analytics worthless.
	"is_bot" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "click_events" IS 'Append-only raw click log. It is never updated, which is what lets it be partitioned by time, written to cheaply and dropped wholesale once its retention window passes.';
COMMENT ON COLUMN "click_events"."id" IS 'Monotonic event id. In production this table is partitioned by day and old partitions are dropped rather than deleted row by row.';
COMMENT ON COLUMN "click_events"."link_id" IS 'Link that was hit.';
COMMENT ON COLUMN "click_events"."occurred_at" IS 'Hit time. Also the partition key.';
COMMENT ON COLUMN "click_events"."ip_hash" IS 'Salted hash of the client address. The raw IP is never stored - the only question analytics asks is "same visitor?", and a hash answers it without keeping personal data.';
COMMENT ON COLUMN "click_events"."country_code" IS 'ISO 3166-1 alpha-2 from geo-IP lookup. Null when the lookup fails.';
COMMENT ON COLUMN "click_events"."city" IS 'Resolved city, when the geo database has one.';
COMMENT ON COLUMN "click_events"."referer" IS 'Referring URL as sent by the browser, truncated by the application. Null for a direct hit.';
COMMENT ON COLUMN "click_events"."user_agent" IS 'Raw UA string, kept for reprocessing when the parser improves.';
COMMENT ON COLUMN "click_events"."device_type" IS 'desktop | mobile | tablet | bot. Parsed at write time, because parsing 50 million UA strings at read time is not a report, it is an outage.';
COMMENT ON COLUMN "click_events"."browser" IS 'Parsed browser family.';
COMMENT ON COLUMN "click_events"."os" IS 'Parsed operating system family.';
COMMENT ON COLUMN "click_events"."is_bot" IS 'Excluded from the headline click number. Crawlers can be most of the traffic on a public link, and counting them makes analytics worthless.';

CREATE INDEX "idx_click_events_link_time"
ON "click_events" ("link_id", "occurred_at");
CREATE INDEX "idx_click_events_time"
ON "click_events" ("occurred_at");

CREATE TABLE IF NOT EXISTS "click_daily" (
	-- Link being summarised. Part of the composite key.
	"link_id" BIGINT,
	-- UTC calendar day. Part of the composite key, so the rollup is naturally unique per link per day.
	"day" DATE,
	-- Country dimension, or ZZ for unknown. Part of the composite key - keeping one dimension in the rollup covers the chart people actually look at.
	"country_code" CHAR(2),
	-- Total hits, bots excluded.
	"clicks" INTEGER NOT NULL DEFAULT 0,
	-- Distinct ip_hash values that day. Approximate by construction, and honest about it.
	"unique_visitors" INTEGER NOT NULL DEFAULT 0,
	-- Counted separately rather than discarded, so a sudden crawl is visible instead of looking like a traffic spike that never happened.
	"bot_clicks" INTEGER NOT NULL DEFAULT 0,
	-- When the rollup last ran for this key. Lets a backfill find rows it has not reprocessed.
	"computed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("link_id", "day", "country_code")
);

COMMENT ON TABLE "click_daily" IS 'Pre-aggregated daily counts. Charts read this and never touch click_events, which is what makes a two-year analytics view load in milliseconds after the raw events have already been dropped.';
COMMENT ON COLUMN "click_daily"."link_id" IS 'Link being summarised. Part of the composite key.';
COMMENT ON COLUMN "click_daily"."day" IS 'UTC calendar day. Part of the composite key, so the rollup is naturally unique per link per day.';
COMMENT ON COLUMN "click_daily"."country_code" IS 'Country dimension, or ZZ for unknown. Part of the composite key - keeping one dimension in the rollup covers the chart people actually look at.';
COMMENT ON COLUMN "click_daily"."clicks" IS 'Total hits, bots excluded.';
COMMENT ON COLUMN "click_daily"."unique_visitors" IS 'Distinct ip_hash values that day. Approximate by construction, and honest about it.';
COMMENT ON COLUMN "click_daily"."bot_clicks" IS 'Counted separately rather than discarded, so a sudden crawl is visible instead of looking like a traffic spike that never happened.';
COMMENT ON COLUMN "click_daily"."computed_at" IS 'When the rollup last ran for this key. Lets a backfill find rows it has not reprocessed.';

CREATE TABLE IF NOT EXISTS "qr_codes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Link the code encodes. Encoding the short URL rather than the destination is the point: the printed code stays valid when the destination changes.
	"link_id" BIGINT NOT NULL,
	-- svg | png. SVG is the default because a QR code is usually printed and vector scales.
	"image_format" VARCHAR(10) NOT NULL DEFAULT 'svg',
	-- L | M | Q | H. H tolerates a logo covering up to 30% of the code, which is why a branded code needs it.
	"error_correction" CHAR(1) NOT NULL DEFAULT 'M',
	-- Hex colour of the modules. Contrast matters more than brand here; a low-contrast QR code simply does not scan.
	"foreground_color" VARCHAR(9) NOT NULL DEFAULT '#000000',
	-- Hex background colour.
	"background_color" VARCHAR(9) NOT NULL DEFAULT '#FFFFFF',
	-- Centre logo image. Null for a plain code.
	"logo_url" TEXT,
	-- Hits attributed to this QR code, tracked by a query parameter the code embeds. Separate from link click_count so print and digital campaigns can be compared.
	"scan_count" BIGINT NOT NULL DEFAULT 0,
	-- Generation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "qr_codes" IS 'Rendering settings, not the rendered image. Storing the parameters means the image can be regenerated at any size or format on demand, and a printed code never depends on a stored blob surviving.';
COMMENT ON COLUMN "qr_codes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "qr_codes"."link_id" IS 'Link the code encodes. Encoding the short URL rather than the destination is the point: the printed code stays valid when the destination changes.';
COMMENT ON COLUMN "qr_codes"."image_format" IS 'svg | png. SVG is the default because a QR code is usually printed and vector scales.';
COMMENT ON COLUMN "qr_codes"."error_correction" IS 'L | M | Q | H. H tolerates a logo covering up to 30% of the code, which is why a branded code needs it.';
COMMENT ON COLUMN "qr_codes"."foreground_color" IS 'Hex colour of the modules. Contrast matters more than brand here; a low-contrast QR code simply does not scan.';
COMMENT ON COLUMN "qr_codes"."background_color" IS 'Hex background colour.';
COMMENT ON COLUMN "qr_codes"."logo_url" IS 'Centre logo image. Null for a plain code.';
COMMENT ON COLUMN "qr_codes"."scan_count" IS 'Hits attributed to this QR code, tracked by a query parameter the code embeds. Separate from link click_count so print and digital campaigns can be compared.';
COMMENT ON COLUMN "qr_codes"."created_at" IS 'Generation time.';

CREATE INDEX "idx_qr_codes_link"
ON "qr_codes" ("link_id");

CREATE TABLE IF NOT EXISTS "blocked_domains" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Registrable domain to refuse, stored normalised and lowercased. Matching is on the registrable domain so a new subdomain does not dodge the block.
	"hostname" VARCHAR(253) NOT NULL UNIQUE,
	-- phishing | malware | spam | trademark | manual. Recorded because a block will eventually be appealed.
	"reason" VARCHAR(40) NOT NULL,
	-- manual | safe_browsing | phishtank | partner_feed. Distinguishes an operator decision from an imported feed that may later retract it.
	"source" VARCHAR(40) NOT NULL DEFAULT 'manual',
	-- Blocks every subdomain too. The default is true because phishing operations spin up subdomains far faster than a blocklist can be updated.
	"match_subdomains" BOOLEAN NOT NULL DEFAULT true,
	-- When an imported entry should be re-evaluated. Null for a permanent manual block.
	"expires_at" TIMESTAMPTZ,
	-- When the entry was added.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocked_domains" IS 'The denylist checked before a link is created and again asynchronously afterwards. A shortener hides the destination by design, which makes it an attractive phishing tool and makes this table non-optional.';
COMMENT ON COLUMN "blocked_domains"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "blocked_domains"."hostname" IS 'Registrable domain to refuse, stored normalised and lowercased. Matching is on the registrable domain so a new subdomain does not dodge the block.';
COMMENT ON COLUMN "blocked_domains"."reason" IS 'phishing | malware | spam | trademark | manual. Recorded because a block will eventually be appealed.';
COMMENT ON COLUMN "blocked_domains"."source" IS 'manual | safe_browsing | phishtank | partner_feed. Distinguishes an operator decision from an imported feed that may later retract it.';
COMMENT ON COLUMN "blocked_domains"."match_subdomains" IS 'Blocks every subdomain too. The default is true because phishing operations spin up subdomains far faster than a blocklist can be updated.';
COMMENT ON COLUMN "blocked_domains"."expires_at" IS 'When an imported entry should be re-evaluated. Null for a permanent manual block.';
COMMENT ON COLUMN "blocked_domains"."created_at" IS 'When the entry was added.';

CREATE TABLE IF NOT EXISTS "safety_scans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Link that was scanned.
	"link_id" BIGINT NOT NULL,
	-- clean | suspicious | malicious | unreachable. Recorded per scan, because a destination that was clean at creation can be compromised months later.
	"verdict" VARCHAR(20) NOT NULL,
	-- Service that returned the verdict, e.g. safe_browsing. Kept so a false positive can be attributed and appealed.
	"provider" VARCHAR(40) NOT NULL,
	-- URL after following redirects. The check that matters: a clean landing page can bounce straight to a malicious one.
	"final_url" TEXT,
	-- Raw provider response, kept verbatim for appeals and for reprocessing when the parser changes.
	"details" JSONB,
	-- Scan time.
	"scanned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "safety_scans" IS 'Append-only scan history rather than a verdict column on links. Rescanning is the whole point - links are scanned again on a schedule, and a change from clean to malicious is the event that trips is_disabled.';
COMMENT ON COLUMN "safety_scans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "safety_scans"."link_id" IS 'Link that was scanned.';
COMMENT ON COLUMN "safety_scans"."verdict" IS 'clean | suspicious | malicious | unreachable. Recorded per scan, because a destination that was clean at creation can be compromised months later.';
COMMENT ON COLUMN "safety_scans"."provider" IS 'Service that returned the verdict, e.g. safe_browsing. Kept so a false positive can be attributed and appealed.';
COMMENT ON COLUMN "safety_scans"."final_url" IS 'URL after following redirects. The check that matters: a clean landing page can bounce straight to a malicious one.';
COMMENT ON COLUMN "safety_scans"."details" IS 'Raw provider response, kept verbatim for appeals and for reprocessing when the parser changes.';
COMMENT ON COLUMN "safety_scans"."scanned_at" IS 'Scan time.';

CREATE INDEX "idx_safety_scans_link_time"
ON "safety_scans" ("link_id", "scanned_at");
CREATE INDEX "idx_safety_scans_verdict"
ON "safety_scans" ("verdict");

